// 2. 建立高速查詢字典
const SEVEN_STORES_MAP = {};

// 3. 系統自動在背景解析 (只會執行一次，不拖慢網頁速度)
(() => {
  if (!RAW_711_DATA) return;
  // 清除標題，並把每個 6 碼數字前面加上換行符號來分割資料
  const cleanData = RAW_711_DATA.replace(/店號店名地址/g, '').replace(/(\d{6})(?=[^\d])/g, '\n$1');
  const lines = cleanData.split('\n');
  
  // 台灣縣市正則表達式，用來精準切出「店名」
  const cityRegex = /(台北市|新北市|基隆市|宜蘭縣|桃園市|新竹市|新竹縣|苗栗縣|台中市|彰化縣|南投縣|雲林縣|嘉義市|嘉義縣|台南市|高雄市|屏東縣|花蓮縣|台東縣|澎湖縣|金門縣|連江縣)/;
  
  lines.forEach(line => {
    line = line.trim();
    if (line.length < 10) return;
    
    // 取得前6碼為店號
    const id = line.substring(0, 6);
    if (!/^\d{6}$/.test(id)) return;
    
    // 剩下的字串去尋找縣市名稱的起點
    const rest = line.substring(6);
    const match = rest.match(cityRegex);
    if (match) {
      // 縣市名稱之前的字就是「店名」
      const name = rest.substring(0, match.index).trim();
      SEVEN_STORES_MAP[name] = id;           // 存入: 千翔 -> 110817
      SEVEN_STORES_MAP[name + "門市"] = id; // 存入: 千翔門市 -> 110817
      SEVEN_STORES_MAP[id] = id;             // 存入: 110817 -> 110817
    }
  });
})();

// 4. 升級版的：取得 7-11 店號函數
const getSevenStoreId = (storeName) => {
  if (!storeName) return null;
  const cleanStr = storeName.trim();

  // 情況 A：客人很乖有打括號，例如 "鑫華門市 (981245)"
  const matchParentheses = cleanStr.match(/\((\d{6})\)/);
  if (matchParentheses) return matchParentheses[1];

  // 情況 B：客人直接輸入六碼數字，例如 "981245" 或 "鑫華 981245"
  const match6Digits = cleanStr.match(/\d{6}/);
  if (match6Digits) return match6Digits[0];

  // 情況 C：客人只打店名，例如 "千翔門市" 或 "7-11 千翔"
  // 過濾掉多餘的字，直接去資料庫找
  const cleanName = cleanStr.replace(/7-11/i, '').replace(/統一超商/i, '').trim();
  if (SEVEN_STORES_MAP[cleanName]) {
    return SEVEN_STORES_MAP[cleanName]; // 成功從資料庫找到對應的六碼！
  }

  // 都找不到就回傳 null
  return null;
};
